package com.example.starter.calibration.model;

/**
 * 合成不确定度计算口径。
 */
public enum UncertaintyMethod {

    /**
     * 公开的 RSS 口径：假设各分量互不相关，
     * 合成不确定度 u_c = sqrt(Σ u_i²)（平方和开根）。
     */
    RSS_V1
}

package com.example.starter.calibration.model;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 仪器不确定度阈值版本。阈值只增不改：发布修订即产生新版本，旧预算与旧放行继续引用旧版本。
 *
 * @param id             阈值版本行 ID（自增）
 * @param instrumentId   仪器 ID
 * @param version        仪器内版本号，从 1 起逐版递增，不回用
 * @param maxUncertainty 合成不确定度上限（含端点），非负，最多 6 位小数
 * @param createdBy      发布人（X-Actor-Id）
 * @param createdAt      发布时间（UTC）
 */
public record UncertaintyThreshold(
        long id,
        String instrumentId,
        int version,
        BigDecimal maxUncertainty,
        String createdBy,
        Instant createdAt) {
}

package com.example.starter.calibration.model;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 不确定度分量。隶属于某一不可变预算版本；同一预算内名称唯一，值非负。
 *
 * @param id      分量 ID（自增）
 * @param budgetId 所属预算版本 ID
 * @param name    分量名称，预算内唯一，区分大小写
 * @param value   分量标准不确定度，非负，最多 6 位小数
 * @param ordinal 提交序号，从 0 起；明细与历史按 (ordinal, id) 稳定排序
 * @param createdAt 分量固化时间（UTC，与预算版本一致）
 */
public record UncertaintyComponent(
        long id,
        long budgetId,
        String name,
        BigDecimal value,
        int ordinal,
        Instant createdAt) {
}

