    public IdempotentRequestRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 插入成功请求的幂等记录。request_id 冲突抛 DuplicateKeyException；
     * 外层事务回滚时本行随之回滚，因此失败不占键。
     */
    public void insert(IdempotentRequest request) {
