    public Optional<UncertaintyThreshold> findCurrent(String instrumentId) {
        return jdbc.query(
                "SELECT * FROM uncertainty_threshold WHERE instrument_id = ? "
                        + "ORDER BY version DESC LIMIT 1",
                MAPPER, instrumentId).stream().findFirst();
    }

    /**
