    public int currentVersionNumber(String instrumentId) {
        Integer v = jdbc.queryForObject(
                "SELECT COALESCE(MAX(version), 0) FROM uncertainty_threshold WHERE instrument_id = ?",
                Integer.class, instrumentId);
        return v == null ? 0 : v;
    }
