package com.example.starter.calibration.repo;

import java.sql.PreparedStatement;
import java.time.LocalDateTime;
import java.util.Optional;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import com.example.starter.calibration.model.IdempotentRequest;

/**
 * 写接口幂等记录持久化。request_id 主键：插入成功者占位，重复主键即重放/异参冲突。
 */
@Repository
public class IdempotentRequestRepository {

    private static final RowMapper<IdempotentRequest> MAPPER = (rs, rowNum) -> new IdempotentRequest(
            rs.getString("request_id"),
            rs.getString("operator"),
            rs.getString("operation_type"),
            rs.getString("fingerprint"),
            rs.getInt("http_status"),
            rs.getString("response_snapshot"),
            JdbcTimes.fromDb(rs.getObject("created_at", LocalDateTime.class)));

    private final JdbcTemplate jdbc;

    public IdempotentRequestRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 插入成功请求的幂等记录。request_id 冲突抛 DuplicateKeyException；
     * 外层事务回滚时本行随之回滚，因此失败不占键。
     */
    public void insert(IdempotentRequest request) {
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO idempotent_request "
                            + "(request_id, operator, operation_type, fingerprint, http_status, "
                            + "response_snapshot, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)");
            ps.setString(1, request.requestId());
            ps.setString(2, request.operator());
            ps.setString(3, request.operationType());
            ps.setString(4, request.fingerprint());
            ps.setInt(5, request.httpStatus());
            ps.setString(6, request.responseSnapshot());
            ps.setObject(7, JdbcTimes.toDb(request.createdAt()));
            return ps;
        });
    }

    /**
     * 按 requestId 查询已成功的幂等记录。
     */
    public Optional<IdempotentRequest> find(String requestId) {
        return jdbc.query("SELECT * FROM idempotent_request WHERE request_id = ?", MAPPER, requestId)
                .stream().findFirst();
    }

    /**
     * 按 requestId 查询并加行锁（须在事务内调用），使同 requestId 并发请求串行裁决。
     */
    public Optional<IdempotentRequest> findForUpdate(String requestId) {
        return jdbc.query(
                "SELECT * FROM idempotent_request WHERE request_id = ? FOR UPDATE",
                MAPPER, requestId).stream().findFirst();
    }

    /**
     * 尝试插入占位行（响应快照暂为 null）。同 requestId 并发时唯一成功者继续，
     * 其余抛 DuplicateKeyException 后改为等待/读取首次结果。
     */
    public boolean tryInsertPlaceholder(String requestId, String operator,
                                        String operationType, String fingerprint) {
        try {
            jdbc.update("INSERT INTO idempotent_request "
                            + "(request_id, operator, operation_type, fingerprint, http_status, "
                            + "response_snapshot, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
                    requestId, operator, operationType, fingerprint, 0, null,
                    JdbcTimes.toDb(java.time.Instant.now()));
            return true;
        } catch (DuplicateKeyException ex) {
            return false;
        }
    }
}

