            requests.finalizeSuccess(requestId.trim(), httpStatus, snapshot);
        } catch (com.fasterxml.jackson.core.JsonProcessingException ex) {
            throw new IllegalStateException("序列化幂等响应快照失败", ex);
        }
    }

