            }
            try {
                Thread.sleep(WAIT_STEP_MILLIS);
            } catch (InterruptedException ex) {
                Thread.currentThread().interrupt();
                throw ApiException.conflict("IDEMPOTENCY_INTERRUPTED", "等待幂等前序请求时被中断");
            }
        }
        return found.get();
    }
}

